scripts.rev3_fits.py:
# rev3 (EXP-687 cycle-3) sensitivity + power-at-formula-amplitude analysis. NOT PRE-REGISTERED.
# Inputs: /tmp/ecl (INTERMAGNET 1-min, fetched 2026-09-26), /tmp/ecl2/ctl (ASC/KOU/HER, fetched 2026-09-27), lib.py/tests.py from rev2.
import sys, json, hashlib; sys.path.insert(0,'/tmp/ecl2')
import numpy as np
from lib import *
from tests import lag
G1,G4=hm('16:59'),hm('21:01')
def gauss(c,sig):
    t=np.arange(1440); return np.exp(-0.5*((t-c)/sig)**2)
def jfit(dev,idx,s,quad=False):
    y=dev[idx]; ok=np.isfinite(y)
    if ok.mean()<0.9: return np.nan
    u=(idx-idx.mean())/60.0
    cols=[np.ones(len(idx)),u]+([u**2] if quad else [])+[s[idx]]
    X=np.c_[tuple(cols)][ok]
    return float(np.linalg.lstsq(X,y[ok],rcond=None)[0][-1])
FR=json.load(open('/tmp/ecl3/frozen_b2m001.json'))  # dome coverage/FSF per station, frozen file
BOU_B,W004_B=-10.9,-22.24
STATIONS=['EBR','SPT','HAD','CLF','NGK','ESK','LER','GUI']
SIGMAS=[3,5,10,20,30]; TAUS=[0,15,30,60]; KSIG=[2,3,5]
def templates(s):
    c1,tm,c4=contacts(s); ob=obsc_series(s)
    wl=np.arange(c1-60,c4+61); wg=np.arange(G1-60,G4+61); T={}
    for t in TAUS: x=lag(ob,t); T[f'obsc_tau{t}']=(x/x.max(),wl)
    for sg in SIGMAS:
        T[f'c14_local_sig{sg}']=(gauss(c1,sg)+gauss(c4,sg),wl)
        T[f'c14_global_sig{sg}']=(gauss(G1,sg)+gauss(G4,sg),wg)
    return T
def run(s, comp, series_station=None):
    """fit templates of station s to data of series_station (default s)"""
    ds=series_station or s; d=load(ds); out={}
    fr=FR.get(s,{})
    amps={'PRED095_-17':-17.0,'PRED095_-21':-21.0}
    if fr:
        amps['formula_BOU_domecov']=BOU_B*fr['cov']*fr['fsf']
        amps['formula_W004_domecov']=W004_B*fr['cov']*fr['fsf']
        amps['formula_BOU_ephemcov']=BOU_B*O[s]['max_obsc']*fr['fsf']
    for name,(tp,w) in templates(s).items():
        for quad in (False,True):
            ev=None; nul=[]; devs=[]
            for day in sorted(d):
                b,_=base(d,comp,Q,exclude=day); x=d[day][comp]-b
                a=jfit(x,w,tp,quad)
                if not np.isfinite(a): continue
                if day==EVD: ev=a
                elif max(KPD[day][4:8])<=3.0: nul.append(a); devs.append(x)
            if ev is None or len(nul)<8: continue
            nul=np.array(nul); mu,sd=float(nul.mean()),float(nul.std(ddof=1))
            rec=dict(A=round(ev,2),null_mean=round(mu,2),null_sd=round(sd,2),z=round((ev-mu)/sd,2),n_null=len(nul),
                     detect_threshold_nT={f'{k}sigma':round(mu-k*sd,2) for k in KSIG})
            if series_station is None:
                pw={}
                for an,av in amps.items():
                    fits=np.array([jfit(x+av*tp,w,tp,quad) for x in devs])
                    pw[an]=dict(amp_nT=round(av,2),**{f'power_{k}sigma':round(float(np.mean(fits<mu-k*sd)),2) for k in KSIG})
                rec['injection_power']=pw
            out[f"{name}|{'quad' if quad else 'lin'}"]=rec
    return out
if __name__=='__main__':
    R={'_meta':dict(script='rev3_fits.py',null_days='control days 2026-07-13..08-11 with max Kp(12-24UT)<=3, leave-one-out baseline',
        amplitude_sets='PRED-095 -17/-21; dome formula baseline x coverage x FSF with BOU -10.9 and W004 -22.24, dome published coverage; BOU with ephemeris obscuration',
        power='fraction of null days where fit of (real deviation + A x template) falls below null_mean - k x null_sd')}
    for comp in ['Z','H']:
        for s in STATIONS:
            R[f'{comp}|{s}']=run(s,comp); print(comp,s,'done',flush=True)
    # CTL-1 with quadratic trend: priority-station templates fitted to non-eclipsed controls
    for cs in ['ASC','KOU','HER']:
        for s in ['EBR','SPT','HAD','CLF','NGK','ESK']:
            r=run(s,'Z',series_station=cs)
            R[f'CTL|Z|{cs}|{s}']={k:v for k,v in r.items() if k.startswith('obsc_tau0') or k.startswith('obsc_tau30') or k.startswith('c14_global_sig10')}
        print('ctl',cs,flush=True)
    json.dump(R,open('rev3_fits.json','w'),indent=1)
    print('sha256',hashlib.sha256(open('rev3_fits.json','rb').read()).hexdigest())

scripts.rev3_win010_profile.py:
# WIN-010 site-registered profile test (data/wins.json id=010 detail_verdict_text: residual (observed dZ)/(baseline x coverage^alpha),
# alpha in {0.5,0.8,1.0,1.2,1.5}; dome FSF profile vs binary CGM-latitude profile (in-band 30-50 deg CGM = 1, out-of-band <= 0.3,
# NGK marginal); both coverage inputs). Evaluated post hoc on 2026-09-28. NOT OTS-anchored (site-registered only).
import json,hashlib,numpy as np
R=json.load(open('/tmp/ecl3/rev3_fits.json')); FR=json.load(open('/tmp/ecl3/frozen_b2m001.json')); O=json.load(open('/tmp/ecl/obsc.json'))
BASE=-10.9; ALPHAS=[0.5,0.8,1.0,1.2,1.5]
ST=['EBR','SPT','CLF','GUI','NGK','HAD','ESK','LER']   # COI: no data
CGM={'EBR':42.9,'SPT':42.4,'CLF':49.6,'GUI':33.2,'NGK':51.85,'HAD':53.6,'ESK':57.5,'LER':61.8}  # WIN-010 prose, centred dipole IGRF-14 2020 pole
INBAND=['EBR','SPT','CLF','GUI']; OUT=['HAD','ESK','LER']; DISC=['LER','HAD','ESK','GUI']
def prof(kind,ngk):
    if kind=='dome_FSF': return {s:FR[s]['fsf'] for s in ST}
    p={s:1.0 for s in INBAND}; p.update({s:(0.3 if kind=='maglat_0.3' else 0.0) for s in OUT}); p['NGK']=ngk; return p
def wls(R_,S_,P):
    x=np.array([P[s] for s in R_]); y=np.array([R_[s] for s in R_]); w=1/np.array([S_[s] for s in R_])**2
    if np.sum(w*x*x)==0: return dict(k=0.0,k_se=float('nan'),k_z=float('nan'),chi2=float(np.sum(w*y*y)),n=len(y))
    k=np.sum(w*x*y)/np.sum(w*x*x); se=1/np.sqrt(np.sum(w*x*x)); chi=float(np.sum(w*(y-k*x)**2))
    return dict(k=round(float(k),3),k_se=round(float(se),3),k_z=round(float(k/se),2),chi2=round(chi,2),n=len(y))
out={}
for comp in ['Z','H']:
  for tn in ['obsc_tau0|lin','obsc_tau0|quad','obsc_tau30|lin']:
    for covin in ['dome_coverage','ephemeris_obscuration']:
      for a in ALPHAS:
        Rr={};Sr={}
        for s in ST:
            f=R[f'{comp}|{s}'][tn]; cov=FR[s]['cov'] if covin=='dome_coverage' else O[s]['max_obsc']
            den=BASE*cov**a; Rr[s]=(f['A']-f['null_mean'])/den; Sr[s]=f['null_sd']/abs(den)
        for subset,keys in [('all8',ST),('discriminating_LER_HAD_ESK_GUI',DISC)]:
            RR={s:Rr[s] for s in keys}; SS={s:Sr[s] for s in keys}
            res={}
            for kind in ['dome_FSF','maglat_0.3','maglat_0']:
                for ngk in ([None] if kind=='dome_FSF' else [1.0,0.3]):
                    P=prof(kind,ngk if ngk is not None else 1.0)
                    res[kind+('' if ngk is None else f'|NGK={ngk}')]=wls(RR,SS,P)
            out[f'{comp}|{tn}|{covin}|alpha{a}|{subset}']=dict(residuals={s:round(Rr[s],3) for s in keys},residual_sd={s:round(Sr[s],3) for s in keys},fits=res,
                winner=min(res,key=lambda k:res[k]['chi2']))
json.dump(out,open('rev3_win010_profile.json','w'),indent=1)
# summary
for k,v in out.items():
    if 'lin' in k and 'tau0' in k:
        f=v['fits']; print(k,'| dome k=%.2f±%.2f chi2 %.1f | maglat0.3(NGK1) k=%.2f±%.2f chi2 %.1f | maglat0 chi2 %.1f | win %s'%(f['dome_FSF']['k'],f['dome_FSF']['k_se'],f['dome_FSF']['chi2'],f['maglat_0.3|NGK=1.0']['k'],f['maglat_0.3|NGK=1.0']['k_se'],f['maglat_0.3|NGK=1.0']['chi2'],f['maglat_0|NGK=1.0']['chi2'],v['winner']))
print('sha256',hashlib.sha256(open('rev3_win010_profile.json','rb').read()).hexdigest())

scripts.rev3_profile_ctl.py:
# Control-day calibration of the WIN-010 profile test (post hoc, NOT pre-registered): run the identical Z/H obscuration-template
# profile comparison on every control day (station templates/windows unchanged) and compare with the eclipse day.
import sys,json,hashlib; sys.path.insert(0,'/tmp/ecl2'); sys.path.insert(0,'/tmp/ecl3')
import numpy as np
from lib import *
from tests import lag
from rev3_fits import jfit
FR=json.load(open('/tmp/ecl3/frozen_b2m001.json'))
ST=['EBR','SPT','CLF','GUI','NGK','HAD','ESK','LER']; DISC=['LER','HAD','ESK','GUI']
INB=['EBR','SPT','CLF','GUI','NGK']; OUT=['HAD','ESK','LER']
def prof(kind): return {s:(FR[s]['fsf'] if kind=='dome' else (1.0 if s in INB else 0.3)) for s in ST}
out={}
for comp in ['Z','H']:
  for quad in (False,True):
    A={}   # station -> day -> fit
    for s in ST:
        d=load(s); c1,tm,c4=contacts(s); ob=obsc_series(s); w=np.arange(c1-60,c4+61); tp=ob/ob.max()
        A[s]={}
        for day in sorted(d):
            b,_=base(d,comp,Q,exclude=day); a=jfit(d[day][comp]-b,w,tp,quad)
            if np.isfinite(a): A[s][day]=a
    days=sorted(set.intersection(*[set(A[s]) for s in ST]))
    ok=[dd for dd in days if dd==EVD or max(KPD[dd][4:8])<=3.0]
    rows=[]
    for day in ok:
        R_={};S_={}
        for s in ST:
            nul=np.array([A[s][x] for x in ok if x not in (day,EVD)]); mu,sd=nul.mean(),nul.std(ddof=1)
            den=-10.9*FR[s]['cov']; R_[s]=(A[s][day]-mu)/den; S_[s]=sd/abs(den)
        res={}
        for sub,keys in [('all8',ST),('disc',DISC)]:
            for kind in ['dome','maglat']:
                P=prof(kind); x=np.array([P[s] for s in keys]); y=np.array([R_[s] for s in keys]); wt=1/np.array([S_[s] for s in keys])**2
                k=np.sum(wt*x*y)/np.sum(wt*x*x); se=1/np.sqrt(np.sum(wt*x*x)); res[f'{sub}|{kind}']=(float(k/se),float(np.sum(wt*(y-k*x)**2)))
        rows.append(dict(day=day,**{f'{k}|kz':round(v[0],2) for k,v in res.items()},**{f'{k}|chi2':round(v[1],2) for k,v in res.items()}))
    ev=[r for r in rows if r['day']==EVD][0]; ct=[r for r in rows if r['day']!=EVD]
    summ={}
    for sub in ['all8','disc']:
        summ[sub]=dict(event_dome_kz=ev[f'{sub}|dome|kz'],event_dchi2_maglat_minus_dome=round(ev[f'{sub}|maglat|chi2']-ev[f'{sub}|dome|chi2'],2),
            n_control=len(ct),control_dome_wins=sum(r[f'{sub}|maglat|chi2']>r[f'{sub}|dome|chi2'] for r in ct),
            control_dome_kz_ge_event=sum(r[f'{sub}|dome|kz']>=ev[f'{sub}|dome|kz'] for r in ct),
            control_dchi2_ge_event=sum((r[f'{sub}|maglat|chi2']-r[f'{sub}|dome|chi2'])>=(ev[f'{sub}|maglat|chi2']-ev[f'{sub}|dome|chi2']) for r in ct),
            control_abs_dome_kz_ge_event=sum(abs(r[f'{sub}|dome|kz'])>=abs(ev[f'{sub}|dome|kz']) for r in ct))
    out[f"{comp}|obsc_tau0|{'quad' if quad else 'lin'}|dome_coverage|alpha1.0"]=dict(summary=summ,rows=rows)
    print(comp,quad,json.dumps(summ))
json.dump(out,open('rev3_profile_ctl.json','w'),indent=1)
print('sha256',hashlib.sha256(open('rev3_profile_ctl.json','rb').read()).hexdigest())

scripts.rev3_profile_shift.py:
# Time-shift control and leave-one-station-out for the WIN-010 Z profile result (post hoc, NOT pre-registered).
import sys,json,hashlib; sys.path.insert(0,'/tmp/ecl2'); sys.path.insert(0,'/tmp/ecl3')
import numpy as np
from lib import *
from rev3_fits import jfit
FR=json.load(open('/tmp/ecl3/frozen_b2m001.json'))
ST=['EBR','SPT','CLF','GUI','NGK','HAD','ESK','LER']; INB=['EBR','SPT','CLF','GUI','NGK']
def prof(kind,keys): return np.array([FR[s]['fsf'] if kind=='dome' else (1.0 if s in INB else 0.3) for s in keys])
def fitprof(R_,S_,keys,kind):
    x=prof(kind,keys); y=np.array([R_[s] for s in keys]); w=1/np.array([S_[s] for s in keys])**2
    k=np.sum(w*x*y)/np.sum(w*x*x); se=1/np.sqrt(np.sum(w*x*x)); return float(k/se),float(np.sum(w*(y-k*x)**2))
out={}
for comp in ['Z']:
  for quad in (False,True):
    for shift in [-240,-180,-120,0,120,180]:
        A={}
        for s in ST:
            d=load(s); ob=np.roll(obsc_series(s),shift); c1,tm,c4=[x+shift for x in contacts(s)]; w=np.arange(c1-60,c4+61); tp=ob/ob.max()
            if w.max()>=1440 or w.min()<0: A=None; break
            A[s]={}
            for day in sorted(d):
                b,_=base(d,comp,Q,exclude=day); a=jfit(d[day][comp]-b,w,tp,quad)
                if np.isfinite(a): A[s][day]=a
        if A is None: continue
        days=sorted(set.intersection(*[set(A[s]) for s in ST])); ok=[dd for dd in days if dd==EVD or max(KPD[dd][4:8])<=3.0]
        R_={};S_={}
        for s in ST:
            nul=np.array([A[s][x] for x in ok if x!=EVD]); den=-10.9*FR[s]['cov']; R_[s]=(A[s][EVD]-nul.mean())/den; S_[s]=nul.std(ddof=1)/abs(den)
        rec={'all8':dict(zip(['dome_kz','dome_chi2'],fitprof(R_,S_,ST,'dome')),**dict(zip(['maglat_kz','maglat_chi2'],fitprof(R_,S_,ST,'maglat'))))}
        if shift==0:
            for drop in ST:
                keys=[s for s in ST if s!=drop]; rec[f'drop_{drop}']=dict(zip(['dome_kz','dome_chi2'],fitprof(R_,S_,keys,'dome')),**dict(zip(['maglat_kz','maglat_chi2'],fitprof(R_,S_,keys,'maglat'))))
            rec['residual_z_per_station']={s:round(R_[s]/S_[s],2) for s in ST}
        rec={k:({kk:round(vv,2) for kk,vv in v.items()} if isinstance(v,dict) else v) for k,v in rec.items()}
        out[f"{comp}|{'quad' if quad else 'lin'}|shift{shift:+d}min"]=rec
        print(comp,quad,shift,rec['all8'], {k:v['dome_kz'] for k,v in rec.items() if k.startswith('drop')} if shift==0 else '', rec.get('residual_z_per_station',''))
json.dump(out,open('rev3_profile_shift.json','w'),indent=1)
print('sha256',hashlib.sha256(open('rev3_profile_shift.json','rb').read()).hexdigest())

