import numpy as np, itertools, json
def load(fn):
    X=[];T=[]
    for l in open(fn):
        if not l[:4].isdigit(): continue
        p=l.split(); v=[float(x) for x in p[3:7]]
        v=[np.nan if x>=88888 else x for x in v]
        X.append(v); T.append(int(p[1][:2])*60+int(p[1][3:5]))
    a=np.array(X); t=np.array(T)
    H=np.hypot(a[:,0],a[:,1])
    return t,dict(X=a[:,0],Y=a[:,1],Z=a[:,2],F=a[:,3],H=H)
target={'2016-03-09':2.23,'2017-08-21':8.05,'2024-04-08':5.59}
# eclipse windows at/near BOU (UT): 2016 max ~01:57 UT global; 2017 BOU max ~17:46; 2024 BOU partial ~17:30-20:00
win={'2016-03-09':(0,240),'2017-08-21':(16*60+20,19*60+10),'2024-04-08':(17*60,20*60),'2026-08-12':(16*60+59,21*60+1)}
res={}
for d in list(target)+['2026-08-12']:
    t,C=load(f'BOU_{d}.txt')
    for comp in 'XYZHF':
        y=C[comp]
        for wname,(a,b) in [('day',(0,1440)),('evwin',win[d]),('evwin_pm60',(win[d][0]-60,win[d][1]+60))]:
            m=(t>=a)&(t<b)&np.isfinite(y); yy=y[m]; tt=t[m]
            if len(yy)<30: continue
            res[(d,comp,wname,'raw')]=np.std(yy)
            p=np.polyfit(tt,yy,1); res[(d,comp,wname,'lin')]=np.std(yy-np.polyval(p,tt))
            res[(d,comp,wname,'diff')]=np.std(np.diff(yy))
            h=np.array([np.nanmean(yy[(tt>=k)&(tt<k+60)]) for k in range(a,b,60)]); res[(d,comp,wname,'hourly')]=np.nanstd(h)
keys=set(k[1:] for k in res)
out=[]
for k in keys:
    try: v=[res[(d,)+k] for d in target]
    except KeyError: continue
    err=np.sqrt(np.mean([(v[i]-list(target.values())[i])**2 for i in range(3)]))
    out.append((err,k,[round(x,2) for x in v],round(res.get(('2026-08-12',)+k,np.nan),2)))
out.sort()
for o in out[:15]: print(o)
json.dump([dict(rms_err=round(o[0],3),defn='|'.join(o[1]),hist=o[2],d20260812=o[3]) for o in out],open('bou_std.json','w'),indent=1)

